def control(obs):
    look_deg = -23.0
    v_target = -0.9

    hitch_deg = obs.get('hitch_deg', 0.0)
    views = obs.get('views', {})
    cam = views.get('camera')

    target_hitch = 0.0

    if cam and 'walls' in cam and cam['walls']:
        axis_deg = cam.get('axis_deg', -180.0)
        left_dists = []
        right_dists = []

        for b_deg, d in cam['walls']:
            rel_angle = math.radians(b_deg - axis_deg)
            y = d * math.sin(rel_angle)
            x = d * math.cos(rel_angle)

            if 0.5 < x < 5.0:
                if y > 0.2:
                    left_dists.append(y)
                elif y < -0.2:
                    right_dists.append(-y)

        if left_dists and right_dists:
            min_l = min(left_dists)
            min_r = min(right_dists)
            diff = min_l - min_r
            target_hitch = max(-20.0, min(20.0, diff * 15.0))
        elif left_dists:
            if min(left_dists) < 1.0:
                target_hitch = -10.0
        elif right_dists:
            if min(right_dists) < 1.0:
                target_hitch = 10.0

    if cam and cam.get('target_corners'):
        corners = cam['target_corners']
        axis_deg = cam.get('axis_deg', -180.0)
        bay_ys = [d * math.sin(math.radians(b - axis_deg)) for b, d in corners]
        if bay_ys:
            avg_bay_y = sum(bay_ys) / len(bay_ys)
            target_hitch = max(-20.0, min(20.0, avg_bay_y * 12.0))

    error = hitch_deg - target_hitch
    steer_deg = error * 2.8
    steer_deg = max(-34.0, min(34.0, steer_deg))

    return (steer_deg, v_target, look_deg)

