    target_hitch = -6.0

    # Camera corridor analysis
    if cam and 'walls' in cam and cam['walls']:
        axis_deg = cam.get('axis_deg', -180.0)
        left_dists = []
        right_dists = []
        for b_deg, d in cam['walls']:
            rel_angle = math.radians(b_deg - axis_deg)
            x = d * math.cos(rel_angle)
            y = d * math.sin(rel_angle)
            if 0.2 < x < 4.0:
                if y > 0.0:
                    left_dists.append(y)
                else:
                    right_dists.append(-y)
        if left_dists and right_dists:
            diff = min(left_dists) - min(right_dists)
            target_hitch = max(-12.0, min(-2.0, -6.0 + diff * 8.0))
        elif left_dists:
            if min(left_dists) < 1.1:
                target_hitch = -10.0
        elif right_dists:
            if min(right_dists) < 1.1:
                target_hitch = -3.0

    if cam and cam.get('target_corners'):
        corners = cam['target_corners']
        axis_deg = cam.get('axis_deg', -180.0)
        bay_ys = [d * math.sin(math.radians(b - axis_deg)) for b, d in corners]
        if bay_ys:
            avg_bay_y = sum(bay_ys) / len(bay_ys)
            target_hitch = max(-14.0, min(0.0, avg_bay_y * 8.0))

    # Direct/periphery check to protect front right from rail collision
    # Rails on vehicle right are around negative bearings in direct view
    right_clearance = 999.0
    if direct and 'walls' in direct:
        for b_deg, d in direct['walls']:
            if -90 < b_deg < -30:
                y = d * math.sin(math.radians(b_deg))
                right_clearance = min(right_clearance, abs(y))

    # Hitch angle tracking
    error = hitch_deg - target_hitch
    steer_deg = error * 1.5

    # Restrict steer_deg to protect front right
    max_left_steer = 5.0 if right_clearance < 1.4 else 9.0
    steer_deg = max(-10.0, min(max_left_steer, steer_deg))

    return (steer_deg, v_target, look_deg)

